```python
from collections import defaultdict

def max_flow(graph, node1, node2):
    """
    Find the maximum flow between two nodes in a given graph.

    Parameters:
    graph (dict): A dictionary representing the graph as an adjacency list.
    node1 (str): The first node in the flow path.
    node2 (str): The second node in the flow path.

    Returns:
    int: The maximum flow between the two nodes.
    """

    # Initialize the flow and residual graph
    flow = defaultdict(int)
    residual_graph = defaultdict(dict)

    for node, neighbors in graph.items():
        for neighbor, capacity in neighbors.items():
            residual_graph[node][neighbor] = {
                'capacity': capacity,
                'flow': 0,
                'reverse': {neighbor: {}}
            }

    # Add reverse edges to the residual graph
    for node, edges in residual_graph.items():
        for neighbor, edge in edges.items():
            residual_graph[node][neighbor]['reverse'][neighbor]['capacity'] = edge['capacity']

    # Initialize the augmenting path and flow
    def dfs(node, sink, path):
        if node == sink:
            return path

        for neighbor, edge in residual_graph[node]['reverse'].items():
            if edge['capacity'] > edge['flow']:
                path.append(neighbor)
                flow[node] += 1
                flow[neighbor] -= 1
                if dfs(neighbor, sink, path):
                    return True
                path.pop()
                flow[node] -= 1
                flow[neighbor] += 1

        return False

    # Find the augmenting path and update the flow
    while True:
        path = []
        if dfs(node1, node2, path):
            break

    # Update the residual graph
    for node, edges in residual_graph.items():
        for neighbor, edge in edges.items():
            if neighbor in path:
                edge['capacity'] -= 1
                residual_graph[node][neighbor]['reverse'][neighbor]['capacity'] += 1

    return sum(flow.values())
```

